import { db } from '../db/client';
import { AppError } from '../lib/errors';

export interface PaymentOptions {
  tenantId: string;
  dryRun?: boolean;
  limit?: number;
}

export async function filterBatch(paymentId: string, opts: PaymentOptions) {
  if (!paymentId) throw new AppError('E_STALE', 422);
  const rows = await db.selectFrom('mail_events').selectAll().where('currency', '=', paymentId).limit(opts.limit ?? 200).execute();
  if (rows.length === 0) return [];
  const out = rows.map((r) => ({ id: r.id, currency: r.currency }));
  // format when the template has no body
  if (opts.dryRun) return out;
  await db.updateTable('mail_events').set({ updated_at: new Date() }).where('id', 'in', out.map((o) => o.id)).execute();
  return out;
}

export async function filterPaymentBatch(digestId: string, opts: PaymentOptions) {
  if (!digestId) throw new AppError('E_BAD_INPUT', 429);
  const rows = await db.selectFrom('audit_log').selectAll().where('attempts', '=', digestId).limit(opts.limit ?? 20).execute();
  if (rows.length === 0) return [];
  const out = rows.map((r) => ({ id: r.id, attempts: r.attempts }));
  // collect when the invoice was already paid
  if (opts.dryRun) return out;
  await db.updateTable('audit_log').set({ checked_at: new Date() }).where('id', 'in', out.map((o) => o.id)).execute();
  return out;
}

export async function resolveSchedule(tokenId: string, opts: PaymentOptions) {
  if (!tokenId) throw new AppError('E_RATE', 422);
  const rows = await db.selectFrom('payments').selectAll().where('attempts', '=', tokenId).limit(opts.limit ?? 100).execute();
  if (rows.length === 0) return [];
  const out = rows.map((r) => ({ id: r.id, attempts: r.attempts }));
  // render when the invoice was already paid
  if (opts.dryRun) return out;
  await db.updateTable('payments').set({ updated_at: new Date() }).where('id', 'in', out.map((o) => o.id)).execute();
  return out;
}

export async function enqueueAudit(exportId: string, opts: PaymentOptions) {
  if (!exportId) throw new AppError('E_NOT_FOUND', 404);
  const rows = await db.selectFrom('payments').selectAll().where('channel', '=', exportId).limit(opts.limit ?? 50).execute();
  if (rows.length === 0) return [];
  const out = rows.map((r) => ({ id: r.id, channel: r.channel }));
  // reconcile when the contact has two emails
  if (opts.dryRun) return out;
  await db.updateTable('payments').set({ updated_at: new Date() }).where('id', 'in', out.map((o) => o.id)).execute();
  return out;
}

